  for (const line of dictionary.trim().split('\n')) {
    const parts = line.split('|'); const zh = parts.pop();
    for (const word of parts) WORDS.set(normalize(word), zh);
  }
  function refreshDictionary() {
    if (dictionaryPath === location.pathname) return;
    dictionaryPath = location.pathname;
    localCache.clear();
    settingsWords = new Map();
    const parts = dictionaryPath.split('/').filter(Boolean);
    let route = '';
    if (parts[0] === 'settings') route = parts.join('/');
    else if (['orgs', 'organizations'].includes(parts[0]) && parts[2] === 'settings') route = 'orgs/' + parts.slice(2).join('/');
    else if (parts[2] === 'settings') route = 'repository/' + parts.slice(2).join('/');
    settingsPage = Boolean(route);
    if (!settingsPage) return;
    const seen = new Set();
    function include(key) {
      if (seen.has(key) || !SETTINGS_DATA[key]) return;
      seen.add(key);
      const group = SETTINGS_DATA[key];
      for (const dependency of group.include) include(dependency);
      for (const [en, zh] of Object.entries(group.words)) settingsWords.set(normalize(en), zh);
    }
    include('public');
    const menu = route.startsWith('repository/') ? 'repository-settings-menu' : route.startsWith('orgs/') ? 'orgs-settings-menu' : 'settings-menu';
    include(menu);
    if (route === 'orgs/settings') route += '/profile';
    // 新建、编辑和详情页沿用所属设置页词库；别名在生成时保留。
    while (route && !SETTINGS_DATA[route]) route = route.split('/').slice(0, -1).join('/');
    include(route);
  }
  function exact(key) {
    const result = WORDS.get(key) || settingsWords.get(key);
    if (result) return result;
    const ending = key.match(/^(.*?)([.:!?])$/);
    if (!ending) return null;
    const base = WORDS.get(ending[1]) || settingsWords.get(ending[1]);
    if (!base) return null;
    return /[。！？：]$/.test(base) ? base : base + ({'.':'。', ':':'：', '!':'！', '?':'？'}[ending[2]]);
  }
  function local(text) {
    refreshDictionary();
    if (localCache.has(text)) return localCache.get(text);
    const key = normalize(text);
    let result = exact(key);
    const count = key.match(/^(\d[\d,.]*[km]?\+?)\s+(issues?|pull requests?|commits?|branches|tags?|releases?|files?|comments?|contributors?|forks?|stars?|open|closed|merged)$/);
    if (!result && count && exact(count[2])) result = count[1] + ' ' + exact(count[2]);
    const suffix = key.match(/^(.+?)\s+(\d[\d,.]*[km]?\+?)$/);
    if (!result && suffix && exact(suffix[1])) result = exact(suffix[1]) + ' ' + suffix[2];
    if (!result && settingsPage) {
      // 只组合全部已知的完整句子或“字段：选项”，避免逐词猜译和遗漏半句。
      const field = key.match(/^(.+?:)\s+(.+)$/);
      if (field && exact(field[1]) && exact(field[2])) result = exact(field[1]) + exact(field[2]);
      const sentences = key.split(/(?<=[.!?])\s+(?=[a-z(])/);
      if (!result && sentences.length > 1 && sentences.length <= 12) {
        const translated = sentences.map(exact);
        if (translated.every(Boolean)) result = translated.join('');
      }
      // 确认文案中的仓库标识保留原大小写，不能把输入要求翻译成另一个值。
      const confirmation = text.match(/^To confirm, type ["“]([^"”]+)["”] in the box below\.?$/i);
      if (!result && confirmation) result = '要确认，请在下面的输入框中键入“' + confirmation[1] + '”。';
    }
    if (localCache.size >= 3000) localCache.clear();
    localCache.set(text, result);
    return result;
  }

  function identityLink(el) {
    const link = el.closest('a[href]');
    if (!link || link.matches('[data-tab-item],[role="tab"]') || link.closest('.UnderlineNav,.tabnav')) return false;
    let url;
    try { url = new URL(link.getAttribute('href'), location.href); } catch { return false; }
    if (url.hostname !== 'github.com') return false;
    const parts = url.pathname.split('/').filter(Boolean);
    if (/\/projects\/\d+(\/|$)/.test(url.pathname)) return !link.matches('.btn,[role="button"]');
    if (parts.length >= 3 && ['blob', 'tree', 'commit', 'milestone'].includes(parts[2])) {
      // 文件行和代码引用优先保留；明确的文件操作按钮仍可翻译。
      return !link.matches('.btn,[role="button"],[data-testid="raw-button"],[data-testid="edit-button"]');
    }
    if (parts.length >= 4 && ['issues', 'pull', 'discussions'].includes(parts[2]) && /^\d+$/.test(parts[3])) {
      return !link.matches('.btn,[role="button"]');
    }
    if (parts.length === 2 && !RESERVED.has(parts[0].toLowerCase())) return true;
    try {
      return parts.length === 1 && !RESERVED.has(parts[0].toLowerCase()) && normalize(link.textContent) === normalize(decodeURIComponent(parts[0]));
    } catch { return true; }
  }
